from solution import max_profit


def test_issue_example():
    """Maximum profit from a maximum of k transactions matches issue example."""
    assert max_profit([1, 5, 2, 3, 7, 6, 4, 5], 3) == 10  # (5-1)+(7-2)+(5-4)=4+5+1=10


def test_issue_rising_single():
    """Maximum profit from a maximum of k transactions is buy-low sell-high for rising prices."""
    assert max_profit([1, 2, 3, 4, 5], 1) == 4  # 5-1=4


def test_issue_best_window_single():
    """Maximum profit from a maximum of k transactions picks the best single window when k is 1."""
    assert max_profit([1, 5, 2, 7], 1) == 6  # 7-1=6 beats (5-1)=4 and (7-2)=5


def test_issue_two_windows():
    """Maximum profit from a maximum of k transactions sums two windows when k is 2."""
    assert max_profit([1, 5, 2, 7], 2) == 9  # (5-1)+(7-2)=4+5=9


def test_issue_k_limits_to_one():
    """Maximum profit from a maximum of k transactions is limited to k windows, not all gains."""
    assert max_profit([1, 4, 2, 5], 1) == 4  # 5-1=4 beats (4-1)=3 and (5-2)=3; sum 6 needs k=2


def test_issue_classic_two():
    """Maximum profit from a maximum of k transactions uses two non-overlapping windows."""
    assert max_profit([3, 2, 6, 5, 0, 3], 2) == 7  # (6-2)+(3-0)=4+3=7


def test_issue_classic_one():
    """Maximum profit from a maximum of k transactions picks best window when only one is allowed."""
    assert max_profit([3, 2, 6, 5, 0, 3], 1) == 4  # (6-2)=4 beats (3-0)=3


def test_issue_declining_floor():
    """Maximum profit from a maximum of k transactions never goes below zero by doing nothing."""
    assert max_profit([5, 4, 3, 2, 1], 2) == 0  # all differences negative so best is 0


def test_issue_empty():
    """Maximum profit from a maximum of k transactions is zero when there are no prices."""
    assert max_profit([], 1) == 0  # no prices so no trade possible =0


def test_contract_zero_k():
    """Maximum of k transactions means k equal to 0 allows no trade so profit is zero."""
    assert max_profit([1, 5, 2, 3], 0) == 0  # 0 transactions allowed so 0


def test_contract_single_price():
    """Maximum profit from a maximum of k transactions needs buy before sell so one price yields zero."""
    assert max_profit([5], 1) == 0  # need 2 prices for buy then sell so 0


def test_contract_large_k_capped():
    """Maximum of k transactions means extra allowance beyond needed gains does not inflate profit."""
    assert max_profit([1, 2, 3, 4], 100) == 3  # (2-1)+(3-2)+(4-3)=1+1+1=3
